function installVideo(videoUrl, posterUrl) {
  const existing = document.getElementById('ayaka-video');
  if (existing) return () => {};
  const reduced = matchMedia('(prefers-reduced-motion:reduce)');
  const scrim = document.createElement('div');
  scrim.id = 'ayaka-scrim';
  scrim.setAttribute('aria-hidden', 'true');
  const video = document.createElement('video');
  video.id = 'ayaka-video';
  video.setAttribute('aria-hidden', 'true');
  video.muted = true;
  video.autoplay = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = 'auto';
  video.poster = posterUrl;
  video.src = videoUrl;
  const sync = () => { if (reduced.matches) video.pause(); else video.play().catch(() => {}); };
  reduced.addEventListener('change', sync);
  document.body.prepend(scrim, video);
  sync();
  return () => {
    reduced.removeEventListener('change', sync);
    video.remove();
    scrim.remove();
  };
}

// Desktop pet: one illustration + procedural motion + local voice lines.
// No network, no model calls, no tokens. Voice files are served by the host route.

